import{_ as t}from"./chunks/mj-before.D3Lz5W5I.js";import{_ as a}from"./chunks/brief-demo-search.BnRB1lM8.js";import{_ as o,o as r,c as s,a4 as n}from"./chunks/framework.DyX1TuK3.js";const b=JSON.parse('{"title":"The Michael Jackson Incident — anatomy of a fake 100%","description":"","frontmatter":{},"headers":[],"relativePath":"en/mj-case.md","filePath":"en/mj-case.md"}'),i={name:"en/mj-case.md"};function l(c,e,h,d,u,m){return r(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="the-michael-jackson-incident-—-anatomy-of-a-fake-100" tabindex="-1">The Michael Jackson Incident — anatomy of a fake 100% <a class="header-anchor" href="#the-michael-jackson-incident-—-anatomy-of-a-fake-100" aria-label="Permalink to &quot;The Michael Jackson Incident — anatomy of a fake 100%&quot;">​</a></h1><blockquote><p>On the semantic-search demo, searching &quot;Michael Jackson&quot; returned a war-crime drama as the #1 result — labeled <strong>100%</strong>. This page records the full path from symptom to root cause, to measured calibration, to the fix.</p></blockquote><h2 id="_1-symptom" tabindex="-1">1. Symptom <a class="header-anchor" href="#_1-symptom" aria-label="Permalink to &quot;1. Symptom&quot;">​</a></h2><img src="'+t+'" alt="Before: the Michael Jackson query returned One Battle After Another at 100%" style="max-width:360px;border:1px solid #333;border-radius:8px;"><p><em>The actual screen at the time: #1 was the war-crime epic &quot;One Battle After Another&quot;, at 100%.</em></p><ul><li>All 600+ titles in the library are films — <strong>nothing related to MJ at all</strong> (no concert films, no music documentaries)</li><li>Yet the query returned a war-crime blockbuster showing a <strong>100% match</strong></li><li>The card&#39;s tags (thriller / crime / on-the-run) had no visible connection to Michael Jackson — users had no way to make sense of it</li></ul><h2 id="_2-root-causes" tabindex="-1">2. Root causes <a class="header-anchor" href="#_2-root-causes" aria-label="Permalink to &quot;2. Root causes&quot;">​</a></h2><p><strong>(a) The 100% was a display artifact.</strong> Internal ranking scores are relative — the RRF fusion score is min-max normalized, and so is the cross-encoder blend — so &quot;the best of this batch&quot; always maps to 1.0. Even when the whole batch is irrelevant, rank #1 still shows 100%.</p><p><strong>(b) Why this particular film?</strong> During query expansion the LLM&#39;s HyDE step imagines a hypothetical plot — for Michael Jackson it dreamed up a &quot;legendary rise-and-struggle&quot; narrative, whose embedding drifted recall toward the most dramatically charged award winners in the library. The expansion also emitted an &quot;American&quot; tag, handing the award-laden American epic an extra condition boost.</p><h2 id="_3-measure-first-can-no-true-match-be-detected" tabindex="-1">3. Measure first: can &quot;no true match&quot; be detected? <a class="header-anchor" href="#_3-measure-first-can-no-true-match-be-detected" aria-label="Permalink to &quot;3. Measure first: can &quot;no true match&quot; be detected?&quot;">​</a></h2><p>Take the best cosine between the <strong>user&#39;s own query vector</strong> (never the HyDE vector — that one is high by construction) and the library. Good and bad queries separate cleanly:</p><table tabindex="0"><thead><tr><th>Query</th><th>top-1 cosine</th></tr></thead><tbody><tr><td>Korean crime thriller</td><td>0.626</td></tr><tr><td>heartwarming Mother&#39;s Day film</td><td>0.603</td></tr><tr><td>family adventure</td><td>0.578</td></tr><tr><td>dark comedy</td><td>0.531</td></tr><tr><td>something like Parasite</td><td>0.488</td></tr><tr><td><strong>Michael Jackson</strong></td><td><strong>0.371</strong></td></tr></tbody></table><p>→ Use that cosine to split into <strong>three confidence tiers</strong> (thresholds 0.52 / 0.45), hot-reloadable config.</p><h2 id="_4-the-fix-evolved-into-three-confidence-tiers" tabindex="-1">4. The fix (evolved into three confidence tiers) <a class="header-anchor" href="#_4-the-fix-evolved-into-three-confidence-tiers" aria-label="Permalink to &quot;4. The fix (evolved into three confidence tiers)&quot;">​</a></h2><ol><li><strong>Three tiers (cosine)</strong>: best original-query cosine splits into high (≥0.52) / mid (0.45–0.52) / low (&lt;0.45). low → honest warning &quot;no strongly relevant results,&quot; while still offering best-guess results as starting points.</li><li><strong>The ceiling carries the honest signal</strong>: high caps at 95% / mid at 68% / low at 42% — #1&#39;s % reflects &quot;is it really in the library,&quot; <strong>no more fake 100%</strong>; tag boosts can&#39;t push it back up.</li><li><strong>CE is not absolute quality</strong>: later measurement showed the cross-encoder rates unrelated films highly too (MJ top = 0.88), so CE only decides <em>ordering</em>; confidence is always anchored to cosine.</li><li><strong>Min-max over the full candidate pool</strong> (not the visible slice) → a film&#39;s % is stable no matter how many results you show.</li><li><strong>Explainable cards</strong>: every result states which conditions it matched and how it was found (semantic / imagined / lexical).</li></ol><blockquote><p>Full design + calibration: <a href="/film-brain/en/honest">Honest match</a>; decision record: ADR 0009.</p></blockquote><h2 id="_5-outcome" tabindex="-1">5. Outcome <a class="header-anchor" href="#_5-outcome" aria-label="Permalink to &quot;5. Outcome&quot;">​</a></h2><p>The same query after the fix: it lands in the low tier, the warning banner appears, scores cap at 42% — and because the &quot;music / dance&quot; condition boosts now work properly, the films that surface are actually music-related. <strong>Better than before the fix.</strong> Honesty didn&#39;t cost the experience; it made the guesses usable.</p><p><img src="'+a+'" alt="search demo"></p><h2 id="takeaways" tabindex="-1">Takeaways <a class="header-anchor" href="#takeaways" aria-label="Permalink to &quot;Takeaways&quot;">​</a></h2><ul><li><strong>Never present relative scores as absolute confidence</strong> — after min-max, rank #1 is always 1.0</li><li><strong>&quot;One more AI scoring layer&quot; isn&#39;t absolute quality</strong> — the cross-encoder rates out-of-domain films highly too (MJ 0.88); trust its ordering, not its numbers</li><li>Generative query expansion (HyDE) hallucinates drift vectors on out-of-domain queries; confidence must anchor on the user&#39;s own words</li><li>Don&#39;t guess thresholds — measure real queries once and the gap speaks for itself</li><li>&quot;Honestly telling the user there&#39;s no match&quot; is a feature, not a flaw</li></ul>',21)])])}const y=o(i,[["render",l]]);export{b as __pageData,y as default};
